// Only trusted instrumentation maps generated by our esbuild transform are used.
const path=require('node:path');
const {createCoverageMap}=require('istanbul-lib-coverage');
const {createSourceMapStore}=require('istanbul-lib-source-maps');

function trustedInputMap(map,filename,source){
 if(!Array.isArray(map.sources)||map.sources.length!==1||path.resolve(map.sources[0])!==path.resolve(filename)||map.sourcesContent?.[0]!==source)throw Error('Uploaded source maps cannot replace instrumentation source identity');
 return map;
}

async function remapCoverage(raw,sources,root='/tmp/job/project'){
 const original=createCoverageMap(raw),store=createSourceMapStore();
 try{
  if(original.files().some(name=>!original.fileCoverageFor(name).data.inputSourceMap))throw Error('Missing input source map');
  const mapped=await store.transformCoverage(original);const files={};
  for(const filename of mapped.files()){
   const relative=path.relative(root,filename).replaceAll('\\','/');
   if(relative.startsWith('../')||path.isAbsolute(relative)||!Object.hasOwn(sources,relative))throw Error('Unknown mapped source');
   const lines=mapped.fileCoverageFor(filename).getLineCoverage(),maximum=sources[relative].split('\n').length;
   if(Object.keys(lines).some(line=>!Number.isInteger(Number(line))||Number(line)<1||Number(line)>maximum))throw Error('Invalid original line mapping');
   files[relative]={executed_lines:Object.keys(lines).filter(l=>lines[l]>0).map(Number),missing_lines:Object.keys(lines).filter(l=>!lines[l]).map(Number)};
  }
  if(!Object.keys(files).length)throw Error('Empty source mapping');
  return {map:mapped,files,kind:'istanbul-original-source',scope:'Original source lines via esbuild source maps; instrumented project modules only; dependencies excluded'};
 }finally{store.dispose()}
}
module.exports={remapCoverage,trustedInputMap};
